(function(){
 const enhanceOne=function(sel){
  if(!sel||sel.dataset.unifiedDropdown==='1'||sel.multiple||sel.size>1)return;
  // Leave the already-custom category input/picker untouched; this enhancer only handles native select elements.
  if(sel.id==='category')return;
  sel.dataset.unifiedDropdown='1';
  const wrap=document.createElement('div');wrap.className='unified-dropdown';
  const trigger=document.createElement('button');trigger.type='button';trigger.className='unified-dropdown-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
  const label=document.createElement('span');label.className='unified-dropdown-label';
  const chev=document.createElement('span');chev.className='unified-dropdown-chevron';chev.setAttribute('aria-hidden','true');chev.textContent='⌄';trigger.append(label,chev);
  const menu=document.createElement('div');menu.className='unified-dropdown-menu';menu.setAttribute('role','listbox');menu.hidden=true;
  const rebuild=function(){
   menu.innerHTML='';
   Array.from(sel.options).forEach(function(opt){if(opt.disabled&&opt.value==='')return;const b=document.createElement('button');b.type='button';b.className='unified-dropdown-option';b.setAttribute('role','option');b.dataset.value=opt.value;b.setAttribute('aria-selected',String(opt.value===sel.value));
    const t=document.createElement('span');t.textContent=opt.textContent.trim();b.appendChild(t);
    if(opt.value===sel.value){const check=document.createElement('span');check.className='unified-dropdown-check';check.textContent='✓';check.setAttribute('aria-hidden','true');b.appendChild(check)}
    b.addEventListener('click',function(){sel.value=opt.value;sel.dispatchEvent(new Event('change',{bubbles:true}));refresh();close();trigger.focus({preventScroll:true})});menu.appendChild(b)
   });
   const chosen=sel.options[sel.selectedIndex];label.textContent=chosen?chosen.textContent.trim():'Select…';
   trigger.setAttribute('aria-label',(sel.getAttribute('aria-label')||sel.labels?.[0]?.textContent||'Select option').trim()+': '+label.textContent);
  };
  const close=function(){menu.classList.remove('is-open');menu.hidden=true;trigger.classList.remove('is-open');trigger.setAttribute('aria-expanded','false')};
  const open=function(){closeAll(wrap);rebuild();menu.hidden=false;menu.classList.add('is-open');trigger.classList.add('is-open');trigger.setAttribute('aria-expanded','true')};
  const refresh=function(){rebuild()};
  trigger.addEventListener('click',function(){if(menu.hidden)open();else close()});
  trigger.addEventListener('keydown',function(e){if(e.key==='Escape'){close()}else if(e.key==='ArrowDown'){e.preventDefault();open();menu.querySelector('button')?.focus()}});
  sel.addEventListener('change',refresh);
  const observer=new MutationObserver(refresh);observer.observe(sel,{childList:true,subtree:true,attributes:true,characterData:true});
  sel.classList.add('native-select-hidden');sel.setAttribute('tabindex','-1');sel.setAttribute('aria-hidden','true');sel.parentNode.insertBefore(wrap,sel);wrap.append(trigger,menu);
  rebuild();
 };
 function closeAll(except){document.querySelectorAll('.unified-dropdown-menu.is-open').forEach(function(m){if(!except.contains(m)){m.classList.remove('is-open');m.hidden=true;const b=m.parentElement?.querySelector('.unified-dropdown-trigger');if(b){b.classList.remove('is-open');b.setAttribute('aria-expanded','false')}}})}
 function run(root){(root||document).querySelectorAll('select').forEach(enhanceOne)}
 document.addEventListener('click',function(e){if(!e.target.closest('.unified-dropdown'))closeAll(document.createElement('div'))});
 document.addEventListener('keydown',function(e){if(e.key==='Escape')closeAll(document.createElement('div'))});
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){run();new MutationObserver(function(records){records.forEach(function(r){r.addedNodes.forEach(function(n){if(n.nodeType===1){if(n.matches?.('select'))enhanceOne(n);run(n)}})})}).observe(document.body,{childList:true,subtree:true})});
 else {run();new MutationObserver(function(records){records.forEach(function(r){r.addedNodes.forEach(function(n){if(n.nodeType===1){if(n.matches?.('select'))enhanceOne(n);run(n)}})})}).observe(document.body,{childList:true,subtree:true})}
})();

